import { JSX, useEffect, useMemo, useState } from "react";
import { IDispatch } from "../ducks/types";
import { IProgram, ISettings } from "../types";
import { INavCommon } from "../models/state";
import {
  Program_dayApproxTimeMs,
  Program_evaluate,
  Program_getDayData,
  Program_getDayName,
  Program_getProgramDay,
  Program_getProgramDayUsedExercises,
} from "../models/program";
import { Surface } from "./surface";
import { NavbarView } from "./navbar";
import { Footer2View } from "./footer2";
import { Button } from "./button";
import { TextareaAutogrow } from "./textareaAutogrow";
import { EditProgram_updateProgram } from "../models/editProgram";
import { Thunk_pullScreen, Thunk_pushToEditProgram } from "../ducks/thunks";
import { Markdown } from "./markdown";
import { TimeUtils_formatHHMM } from "../utils/time";

interface IProps {
  day: number;
  dispatch: IDispatch;
  navCommon: INavCommon;
  program: IProgram;
  settings: ISettings;
}

export function ScreenWeekDayEditor(props: IProps): JSX.Element {
  const evaluatedProgram = Program_evaluate(props.program, props.settings);
  const dayData = Program_getDayData(evaluatedProgram, props.day);
  const currentDay = Program_getProgramDay(evaluatedProgram, props.day);
  const plannerDay = props.program.planner?.weeks[dayData.week - 1]?.days[dayData.dayInWeek - 1];
  const [description, setDescription] = useState(plannerDay?.description ?? "");
  const [exerciseText, setExerciseText] = useState(plannerDay?.exerciseText ?? "");

  useEffect(() => {
    setDescription(plannerDay?.description ?? "");
    setExerciseText(plannerDay?.exerciseText ?? "");
  }, [plannerDay?.description, plannerDay?.exerciseText, props.day]);

  const draftProgram = useMemo(() => {
    const nextProgram: IProgram = {
      ...props.program,
      planner: props.program.planner
        ? {
            ...props.program.planner,
            weeks: props.program.planner.weeks.map((week, weekIndex) => ({
              ...week,
              days: week.days.map((day, dayIndex) => {
                if (weekIndex === dayData.week - 1 && dayIndex === dayData.dayInWeek - 1) {
                  return {
                    ...day,
                    description: description.trim() ? description : undefined,
                    exerciseText,
                  };
                }
                return day;
              }),
            })),
          }
        : undefined,
    };
    return nextProgram;
  }, [dayData.dayInWeek, dayData.week, description, exerciseText, props.program]);

  const draftEvaluatedProgram = useMemo(
    () => Program_evaluate(draftProgram, props.settings),
    [draftProgram, props.settings]
  );
  const draftDay = Program_getProgramDay(draftEvaluatedProgram, props.day);
  const draftExercises = draftDay ? Program_getProgramDayUsedExercises(draftDay) : [];
  const dayError = draftEvaluatedProgram.errors.find(
    (error) => error.dayData.week === dayData.week && error.dayData.dayInWeek === dayData.dayInWeek
  );
  const dayApproxTime =
    draftDay && draftExercises.length > 0 ? TimeUtils_formatHHMM(Program_dayApproxTimeMs(draftDay, props.settings)) : undefined;

  const onSave = (): void => {
    if (dayError) {
      return;
    }
    EditProgram_updateProgram(props.dispatch, draftProgram);
    props.dispatch(Thunk_pullScreen());
  };

  return (
    <Surface
      navbar={
        <NavbarView
          navCommon={props.navCommon}
          dispatch={props.dispatch}
          title="Edit Day"
          subtitle={Program_getDayName(evaluatedProgram, props.day)}
          rightButtons={[
            <Button
              key="week-day-advanced"
              kind="lightgrayv3"
              buttonSize="sm"
              className="text-xs"
              name="week-day-advanced"
              onClick={() => props.dispatch(Thunk_pushToEditProgram(dayData))}
            >
              Advanced
            </Button>,
          ]}
        />
      }
      footer={<Footer2View navCommon={props.navCommon} dispatch={props.dispatch} />}
    >
      <section className="px-4 pb-6">
        <div className="pt-1 text-sm text-text-secondary">
          Edit the notes and the exercise lines for this day only. Save is disabled until the planner syntax is valid.
        </div>

        <section className="p-4 mt-4 border rounded-2xl bg-background-cardpurple border-border-cardpurple">
          <div className="text-sm font-semibold text-text-primary">Day Notes</div>
          <div className="mt-2 text-xs text-text-secondary">
            Use this for cardio, effort targets, recovery reminders, or technique cues.
          </div>
          <div className="mt-3">
            <TextareaAutogrow
              value={description}
              placeholder="Add notes for this day..."
              onChangeText={(value) => setDescription(value)}
              className="p-3 text-sm border rounded-xl bg-background-default border-border-neutral text-text-primary"
            />
          </div>
          {description.trim() && (
            <div className="p-3 mt-3 text-sm border rounded-xl bg-background-default border-border-neutral">
              <div className="mb-2 text-xs font-semibold text-text-secondary">Preview</div>
              <Markdown value={description} />
            </div>
          )}
        </section>

        <section className="p-4 mt-4 border rounded-2xl bg-background-cardpurple border-border-cardpurple">
          <div className="flex items-start justify-between gap-3">
            <div>
              <div className="text-sm font-semibold text-text-primary">Exercise Lines</div>
              <div className="mt-1 text-xs text-text-secondary">
                One exercise per line. Example: <code>Lat Pulldown / 3x6-10</code>
              </div>
            </div>
            <div className="text-right">
              <div className="text-xs text-text-secondary">{draftExercises.length} exercises</div>
              {dayApproxTime && <div className="text-xs text-text-secondary">Approx {dayApproxTime}</div>}
            </div>
          </div>

          <div className="mt-3">
            <TextareaAutogrow
              value={exerciseText}
              placeholder="Bench Press / 3x8&#10;Row / 3x10"
              onChangeText={(value) => setExerciseText(value)}
              className="p-3 font-mono text-sm border rounded-xl bg-background-default border-border-neutral text-text-primary"
            />
          </div>

          {dayError ? (
            <div className="p-3 mt-3 text-sm border rounded-xl bg-background-darkred border-text-error text-text-alwayswhite">
              <div className="font-semibold">Fix planner syntax before saving.</div>
              <div className="mt-1">{dayError.error.message}</div>
              <div className="mt-1 text-xs opacity-80">Line {dayError.error.line}</div>
            </div>
          ) : (
            <div className="p-3 mt-3 text-sm border rounded-xl bg-background-default border-border-neutral text-text-secondary">
              The day parses cleanly.
            </div>
          )}

          {draftExercises.length > 0 && (
            <div className="mt-3 space-y-2">
              {draftExercises.slice(0, 8).map((exercise) => (
                <div key={exercise.key} className="text-sm text-text-primary">
                  {exercise.fullName}
                </div>
              ))}
            </div>
          )}
        </section>

        {currentDay?.description == null && currentDay?.exercises.length === 0 && (
          <div className="p-3 mt-4 text-sm border rounded-xl bg-background-default border-border-neutral text-text-secondary">
            This day is empty right now. Start by pasting one exercise line, then save.
          </div>
        )}

        <div className="grid grid-cols-2 gap-2 mt-4">
          <Button kind="purple" name="save-week-day" onClick={onSave} disabled={!!dayError}>
            Save Changes
          </Button>
          <Button
            kind="lightgrayv3"
            name="open-day-advanced-editor"
            onClick={() => props.dispatch(Thunk_pushToEditProgram(dayData))}
          >
            Advanced Editor
          </Button>
        </div>
      </section>
    </Surface>
  );
}
