import { JSX } from "react";
import { IDispatch } from "../ducks/types";
import { IProgram, ISettings, IStats } from "../types";
import { INavCommon } from "../models/state";
import {
  IEvaluatedProgram,
  Program_evaluate,
  Program_getDayName,
  Program_getProgramDay,
  Program_nextHistoryRecord,
} from "../models/program";
import { Surface } from "./surface";
import { NavbarView } from "./navbar";
import { Footer2View } from "./footer2";
import { GroupHeader } from "./groupHeader";
import { Button } from "./button";
import { HistoryEntryView } from "./historyEntry";
import { EditProgram_setNextDay } from "../models/editProgram";
import { Thunk_pushScreen, Thunk_pushToEditProgram, Thunk_startProgramDay } from "../ducks/thunks";
import { PlanDayUtils_findCalendarDay, PlanDayUtils_getCalendarDayName } from "./planDayUtils";
import { Markdown } from "./markdown";
import { DateUtils_format, DateUtils_formatYYYYMMDD } from "../utils/date";

interface IProps {
  dispatch: IDispatch;
  navCommon: INavCommon;
  program: IProgram;
  settings: ISettings;
  stats: IStats;
}

function getDisplayDay(program: IEvaluatedProgram, navCommon: INavCommon): number {
  if (navCommon.progress?.programId === program.id) {
    return navCommon.progress.day;
  }
  return PlanDayUtils_findCalendarDay(program) ?? program.nextDay;
}

function isProgressFromDate(startTime: number, date: Date = new Date()): boolean {
  return DateUtils_formatYYYYMMDD(startTime) === DateUtils_formatYYYYMMDD(date);
}

export function ScreenToday(props: IProps): JSX.Element {
  const evaluatedProgram = Program_evaluate(props.program, props.settings);
  const calendarDay = PlanDayUtils_findCalendarDay(evaluatedProgram);
  const currentProgress =
    props.navCommon.progress?.programId === props.program.id ? props.navCommon.progress : undefined;
  const isCurrentDayProgress = currentProgress ? isProgressFromDate(currentProgress.startTime) : false;
  const staleProgress = currentProgress && !isCurrentDayProgress ? currentProgress : undefined;
  const displayDay = isCurrentDayProgress ? getDisplayDay(evaluatedProgram, props.navCommon) : calendarDay ?? evaluatedProgram.nextDay;
  const isOngoing = !!currentProgress && isCurrentDayProgress;
  const programDay = Program_getProgramDay(evaluatedProgram, displayDay);
  const preview = isOngoing
    ? currentProgress
    : Program_nextHistoryRecord(props.program, props.settings, props.stats, displayDay);
  const isCalendarMismatch = !isOngoing && calendarDay != null && calendarDay !== evaluatedProgram.nextDay;

  const startDisplayDay = (): void => {
    if (staleProgress) {
      const shouldDiscard = confirm(
        `You still have an unfinished ${staleProgress.dayName} workout from ${DateUtils_format(
          staleProgress.startTime
        )}. Delete it and start ${Program_getDayName(evaluatedProgram, displayDay)} instead?`
      );
      if (!shouldDiscard) {
        props.dispatch(Thunk_startProgramDay(props.program.id));
        return;
      }
      props.dispatch({ type: "DeleteProgress" });
    }
    if (!isOngoing && displayDay !== evaluatedProgram.nextDay) {
      EditProgram_setNextDay(props.dispatch, props.program.id, displayDay);
    }
    props.dispatch(Thunk_startProgramDay(props.program.id));
  };

  return (
    <Surface
      navbar={
        <NavbarView
          navCommon={props.navCommon}
          dispatch={props.dispatch}
          title="Today"
          subtitle={programDay?.name ? `${programDay.name} plan` : undefined}
        />
      }
      footer={<Footer2View navCommon={props.navCommon} dispatch={props.dispatch} />}
    >
      <section className="px-4">
        <div className="pt-1">
          <div className="text-sm font-semibold text-text-primary">
            {Program_getDayName(evaluatedProgram, displayDay)}
          </div>
          <div className="text-xs text-text-secondary">
            Calendar day: {PlanDayUtils_getCalendarDayName()} · Up next in plan: {Program_getDayName(evaluatedProgram, evaluatedProgram.nextDay)}
          </div>
        </div>

        {isCalendarMismatch && calendarDay != null && (
          <div className="p-3 mt-4 text-sm border rounded-xl bg-background-cardpurple border-border-cardpurple">
            <div className="font-semibold">Today&apos;s calendar plan is different from your current next workout.</div>
            <div className="mt-1 text-text-secondary">
              Use {Program_getDayName(evaluatedProgram, calendarDay)} today, or keep {Program_getDayName(evaluatedProgram, evaluatedProgram.nextDay)} as the next session.
            </div>
            <div className="flex gap-2 mt-3">
              <Button
                kind="purple"
                buttonSize="sm"
                name="use-calendar-day"
                onClick={() => {
                  EditProgram_setNextDay(props.dispatch, props.program.id, calendarDay);
                  props.dispatch(Thunk_pushScreen("main", undefined, true));
                }}
              >
                Use Today&apos;s Plan
              </Button>
              <Button
                kind="lightgrayv3"
                buttonSize="sm"
                name="open-week-from-today"
                onClick={() => props.dispatch(Thunk_pushScreen("week", undefined, true))}
              >
                Review Week
              </Button>
            </div>
          </div>
        )}

        {staleProgress && (
          <div className="p-3 mt-4 text-sm border rounded-xl bg-background-cardpurple border-border-cardpurple">
            <div className="font-semibold">You still have yesterday&apos;s workout open.</div>
            <div className="mt-1 text-text-secondary">
              {staleProgress.dayName} was started on {DateUtils_format(staleProgress.startTime)}. Today is{" "}
              {Program_getDayName(evaluatedProgram, displayDay)}.
            </div>
            <div className="flex gap-2 mt-3">
              <Button
                kind="purple"
                buttonSize="sm"
                name="resume-stale-workout"
                onClick={() => props.dispatch(Thunk_startProgramDay(props.program.id))}
              >
                Resume {staleProgress.dayName}
              </Button>
              <Button kind="lightgrayv3" buttonSize="sm" name="start-calendar-day" onClick={startDisplayDay}>
                Start {Program_getDayName(evaluatedProgram, displayDay)}
              </Button>
            </div>
          </div>
        )}

        <div className="p-4 mt-4 border rounded-2xl bg-background-cardpurple border-border-cardpurple">
          <div className="flex items-start justify-between gap-3">
            <div>
              <div className="text-sm font-semibold text-text-primary">
                {isOngoing ? "Ongoing workout" : "Planned workout"}
              </div>
              <div className="text-xs text-text-secondary">{preview?.entries.length ?? 0} exercises scheduled</div>
            </div>
            <Button
              kind="lightgrayv3"
              buttonSize="sm"
              name="edit-today-plan"
              onClick={() => props.dispatch(Thunk_pushScreen("weekDayEditor", { day: displayDay }))}
              disabled={!programDay}
            >
              Edit Day
            </Button>
          </div>

          {programDay?.description && (
            <div className="mt-3 text-sm">
              <Markdown value={programDay.description} />
            </div>
          )}

          <div className="mt-4">
            {preview != null && preview.entries.length > 0 ? (
              preview.entries.map((entry, index) => (
                <HistoryEntryView
                  key={`${entry.id}-${index}`}
                  entry={entry}
                  isNext={!isOngoing}
                  isOngoing={!!isOngoing}
                  isLast={index === preview.entries.length - 1}
                  settings={props.settings}
                  showNotes={true}
                />
              ))
            ) : (
              <div className="p-3 text-sm border rounded-xl bg-background-default border-border-neutral text-text-secondary">
                Nothing is planned for this day yet. Open This Week or the advanced editor to add exercises.
              </div>
            )}
          </div>

          <div className="grid grid-cols-2 gap-2 mt-4">
            <Button kind="purple" name="start-today-workout" onClick={startDisplayDay}>
              {isOngoing ? "Continue Workout" : staleProgress ? `Start ${Program_getDayName(evaluatedProgram, displayDay)}` : "Start Workout"}
            </Button>
            <Button
              kind="grayv2"
              name="today-open-week"
              onClick={() => props.dispatch(Thunk_pushScreen("week", undefined, true))}
            >
              Open This Week
            </Button>
          </div>
        </div>

        <GroupHeader name="Quick Actions" topPadding={true} />
        <div className="grid grid-cols-2 gap-2 pb-6">
          <Button
            kind="lightgrayv3"
            name="today-history"
            onClick={() => props.dispatch(Thunk_pushScreen("history", undefined, true))}
          >
            View History
          </Button>
          <Button kind="lightgrayv3" name="today-advanced" onClick={() => props.dispatch(Thunk_pushToEditProgram())}>
            Advanced Editor
          </Button>
        </div>
      </section>
    </Surface>
  );
}
